1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
9	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
10	 * three letters of the last name, and NNNN a per-city 4-digit zero-padded sequence equal
11	 * to one more than the number of owners already in that city. Runs before the new owner is
12	 * saved, so the count excludes it.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
19	        String lastName = owner.getLastName();
20	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
21	        long inCity = ownerRepository.findAll().stream()
22	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
23	            .count();
24	        long sequence = inCity + 1;
25	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
26	    }
27	}
