3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Emits an audit line on the dedicated {@code AUDIT} logger after a successful create,
12	 * carrying the newly-assigned owner id, its customerCode, its registrationDate and its
13	 * numeric membershipLevel. Runs after {@code save}, so the owner's generated id is available.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
20	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
21	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
22	            ownerMapper.membershipLevel(owner));
23	    }
24	}
