1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "identityKey",
28	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
36	     * present, otherwise {@code PHONE}.
37	     */
38	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
39	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
40	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
41	    }
42	
43	    /**
44	     * The fixed city-to-region table: any city not listed derives locality {@code UNKNOWN}.
45	     */
46	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
47	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
48	
49	    /**
50	     * Derives the owner's locality: the postcode range decides the region first
51	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); when the postcode is absent or in no
52	     * known range, fall back to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
53	     * Brisbane->QLD), or {@code UNKNOWN} when the city is not in the table. Preferring the
54	     * postcode returns the same region for known cities but disambiguates cities that share
55	     * a name.
56	     */
57	    default String locality(Owner owner) {
58	        String byPostcode = regionFromPostcode(owner.getPostcode());
59	        if (byPostcode != null) {
60	            return byPostcode;
61	        }
62	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
63	    }
64	
65	    /**
66	     * Maps a postcode to its region by range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
67	     * or {@code null} when the postcode is absent, non-numeric or in no known range.
68	     *
69	     * <p>Deliberately {@code private}: a {@code String -> String} method visible to MapStruct
70	     * would be treated as an implicit conversion and applied to every String property.
71	     */
72	    private String regionFromPostcode(String postcode) {
73	        if (postcode == null || postcode.isBlank()) {
74	            return null;
75	        }
76	        int code;
77	        try {
78	            code = Integer.parseInt(postcode.trim());
79	        }
80	        catch (NumberFormatException ex) {
81	            return null;
82	        }
83	        if (code >= 2000 && code <= 2099) {
84	            return "NSW";
85	        }
86	        if (code >= 3000 && code <= 3099) {
87	            return "VIC";
88	        }
89	        if (code >= 4000 && code <= 4099) {
90	            return "QLD";
91	        }
92	        return null;
93	    }
94	
95	    /**
96	     * Derives the owner's numeric membership level, assigned on creation. Starts at 1; adds 1 when
97	     * an email address is present; adds 1 when the owner has no namesakes ({@code namesakeCount} is
98	     * 0); capped at 3. (Level 4 is reserved for tenure.)
99	     */
100	    default int membershipLevel(Owner owner) {
101	        int level = 1;
102	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
103	        if (hasEmail) {
104	            level++;
105	        }
106	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
107	        if (noNamesakes) {
108	            level++;
109	        }
110	        return Math.min(level, 3);
111	    }
112	
113	    /**
114	     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
115	     * last two digits of the registrationDate year (e.g. {@code LON-SMI-0007-M26}). Returns {@code null}
116	     * when either source field is absent, so owners without a customer code or registration date
117	     * (e.g. seed data) simply have no membership number.
118	     */
119	    default String membershipNumber(Owner owner) {
120	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
121	            return null;
122	        }
123	        int yy = Math.floorMod(owner.getRegistrationDate().getYear(), 100);
124	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
125	    }
126	
127	    /**
128	     * Computes the owner's Luhn check digit (0-9) over the digits contained in the customerCode.
129	     * Returns {@code null} when the customer code is absent (e.g. seed data).
130	     */
131	    default Integer checkDigit(Owner owner) {
132	        String code = owner.getCustomerCode();
133	        if (code == null) {
134	            return null;
135	        }
136	        int sum = 0;
137	        boolean dbl = true;
138	        for (int i = code.length() - 1; i >= 0; i--) {
139	            char c = code.charAt(i);
140	            if (c < '0' || c > '9') {
141	                continue;
142	            }
143	            int d = c - '0';
144	            if (dbl) {
145	                d *= 2;
146	                if (d > 9) {
147	                    d -= 9;
148	                }
149	            }
150	            sum += d;
151	            dbl = !dbl;
152	        }
153	        return (10 - (sum % 10)) % 10;
154	    }
155	
156	    Owner toOwner(OwnerDto ownerDto);
157	
158	    @Mapping(target = "id", ignore = true)
159	    @Mapping(target = "pets", ignore = true)
160	    Owner toOwner(OwnerFieldsDto ownerDto);
161	
162	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
163	
164	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
165	
166	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
167	        OwnerPageDto ownerPageDto = new OwnerPageDto();
168	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
169	        ownerPageDto.setPage(ownerPage.getNumber());
170	        ownerPageDto.setSize(ownerPage.getSize());
171	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
172	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
173	        return ownerPageDto;
174	    }
175	}
