1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is expressed
9	 * through. Formatted {@code normalizedTelephone|email|householdId}, where the email and householdId
10	 * segments are empty when the owner has none. Two owners are the same identity when their whole
11	 * identityKey is equal; the telephone being part of the key means two members of one household
12	 * (same householdId) with different telephones have different keys and are both allowed.
13	 *
14	 * <p>The telephone is normalized to E.164 (the same way as {@link E164Telephone}) and the email is
15	 * trimmed and lower-cased, so differently-formatted values still produce the same key. The key is
16	 * computed identically for a not-yet-saved owner (in {@link CheckOwnerIdentityUnique}) and for the
17	 * response, so what a client reads back is exactly what collisions are judged on.
18	 */
19	public final class OwnerIdentityKey {
20	
21	    private OwnerIdentityKey() {
22	    }
23	
24	    /** The owner's identity key: {@code normalizedTelephone|email|householdId}. */
25	    public static String of(Owner owner) {
26	        return normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail())
27	                + "|" + (owner.getHouseholdId() == null ? "" : owner.getHouseholdId());
28	    }
29	
30	    private static String normalizeTelephone(String raw) {
31	        if (raw == null) {
32	            return "";
33	        }
34	        String normalized = E164Telephone.normalize(raw);
35	        return normalized != null ? normalized : raw.trim();
36	    }
37	
38	    private static String normalizeEmail(String email) {
39	        if (email == null) {
40	            return "";
41	        }
42	        String trimmed = email.trim();
43	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
44	    }
45	}
