12	
13	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
14	        Owner owner = ownerMapper.toOwner(request);
15	        // Default the registration date to the server's current date when none was supplied.
16	        if (owner.getRegistrationDate() == null) {
17	            owner.setRegistrationDate(LocalDate.now());
18	        }
19	        // The effective registration date must fall on a business day: roll a weekend date
20	        // (supplied or defaulted) forward to the next Monday, so every value derived from it
21	        // (e.g. the membership number's year segment) uses the adjusted date.
22	        owner.setRegistrationDate(BusinessDays.rollForward(owner.getRegistrationDate()));
23	        built.set(owner);
24	    }
25	}
